interface.definition:
a!localVariables(
  local!mappapplication:#"_a-0000eef8-4604-8000-9e54-011c48011c48_1142076"(orgId: ri!orgid, isActive: true()),
  local!appid:if(
    a!isNullOrEmpty(local!mappapplication),
    -1,
    index(
      local!mappapplication,
      #"urn:appian:record-field:v1:0723a91a-4d09-404f-821d-4296dd50e6c6/26a43997-9c33-40cd-a0e1-cf6a4c80387b",
      null()
    )
  ),
  #"SYSTEM_SYSRULES_formLayout_v2"(
    contents: {
      #"_a-0000eef8-4604-8000-9e54-011c48011c48_1141975"(
        selected:ri!selected,
      appid: local!appid
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Submit",
          submit: true,
          saveInto: {
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085463"
            )
          },
          loadingIndicator: true,
          style: "SOLID"
        )
      },
      secondaryButtons: {
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: "Cancel",
          value: true,
          saveInto: {
            a!save(
              target:ri!button,
              value:#"_a-0000eeda-0177-8000-9e52-011c48011c48_1085469"
            )
          },
          validate: false,
          submit: true,
          style: "OUTLINE"
        )
      }
    ),
    titleBar: #"SYSTEM_SYSRULES_headerTemplateFull"(
      title: "Remove Applications",
      secondaryText: "To remove the applications",
      backgroundColor: "ACCENT"
    ),
    showTitleBarDivider: false
  )
)
